import{_ as t,o,c as n,a3 as a}from"./chunks/framework.cNy3aYYk.js";const g=JSON.parse('{"title":"Payments — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payments — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/payments"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payments — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/payments"}]]},"headers":[],"relativePath":"user-guide/payments.md","filePath":"user-guide/payments.md","lastUpdated":1792189050000}'),s={name:"user-guide/payments.md"};function r(i,e,c,l,d,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="payments-—-user-guide" tabindex="-1">Payments — User Guide <a class="header-anchor" href="#payments-—-user-guide" aria-label="Permalink to &quot;Payments — User Guide&quot;">​</a></h1><h2 id="who-can-use-payments" tabindex="-1">Who can use Payments <a class="header-anchor" href="#who-can-use-payments" aria-label="Permalink to &quot;Who can use Payments&quot;">​</a></h2><p>Your workspace must have <strong>Invoices</strong> installed first, then the <strong>Payments</strong> module (both free from Marketplace). Marketplace blocks installing Payments until Invoices is entitled. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>post</code>, <code>void</code>, <code>send</code> as needed).</p><p>Without <strong>assign</strong>, you only see payments assigned to you.</p><blockquote><p><strong>Not the same as Central Billing → Payments.</strong> This module tracks money your workspace receives <em>from your own customers</em>. The platform&#39;s own <strong>Central → Billing → Payments</strong> area (in the platform admin, not here) tracks what your workspace pays the platform for its module subscriptions.</p></blockquote><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Payments</strong> from the sidebar (<strong>Billing</strong>, under Invoices). Search by payment number or reference, filter by status or method, <strong>Paid from/to</strong> (<code>paid_at</code>) and <strong>Created from/to</strong> (with visible labels on each field), toggle <strong>My payments</strong>, and switch KPI cards (My Payments, Draft, Posted, Void, Posted total) to quick-filter the table.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted payment from the row menu</li><li><strong>Delete permanently</strong> requires <code>payments.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="record-a-payment" tabindex="-1">Record a payment <a class="header-anchor" href="#record-a-payment" aria-label="Permalink to &quot;Record a payment&quot;">​</a></h2><ol><li>Click <strong>New payment</strong> (or open <strong>New payment</strong> from a <a href="/user-guide/contacts">Contact</a> record — contact/company are prefilled from the URL)</li><li>Enter the amount, currency, method (Cash, Bank Transfer, Cheque, Card (manual), Other), date paid, reference, and notes</li><li>If <strong>Accounting</strong> is installed, choose <strong>Deposit to</strong> — which cash or bank account will hold this money after collection (defaults to Cash when omitted on post). You can add multiple bank accounts under Finance → Accounts (asset + Cash or bank).</li><li>Add one or more <strong>allocations</strong> — pick an invoice and the amount of this payment to apply to it (draft and unpaid invoices are allowed; cancelled invoices are not). The invoice picker shows <strong>contact name · company · invoice number — balance due</strong>, and you can search by contact name, company name, phone, or invoice number. Choosing an invoice auto-fills <strong>Contact</strong>, <strong>Company</strong>, and <strong>Assignee</strong> from that invoice when those fields are set on the invoice (you can still change them). You can allocate to several invoices, or leave the payment unallocated and add allocations later while still in Draft. When Accounting is installed, allocations must cover the full payment amount before post.</li><li>Optionally adjust the contact, company, or assignee (Contacts/Companies when installed — use <strong>New</strong> beside each picker to create and select without leaving the form when you have create permission; assignee requires <strong>assign</strong>)</li><li>Save with <strong>Create</strong> (returns to the list), <strong>Create &amp; View</strong>, or <strong>Post</strong> (creates then posts when you have permission)</li></ol><p>You can also start recording a payment from an invoice&#39;s detail view — the <strong>Related payments</strong> link jumps you to the Payments module.</p><p>Edit from the row menu or the record page while the payment is still <strong>Draft</strong>. Editing replaces the full allocation list. After <strong>Post</strong>, content is locked; use <strong>Void</strong> and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A payment starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Post</strong> (<code>draft → posted</code>) — applies every allocation to its invoice&#39;s balance: the invoice&#39;s amount paid increases and its status becomes <strong>paid</strong> or <strong>unpaid</strong> from the resulting balance. If the invoice was still a <strong>draft</strong>, posting opens it automatically (no separate Send step). Posting is all-or-nothing: it&#39;s rejected if any allocated invoice has been deleted, is paid/cancelled, or if the allocated amount would exceed that invoice&#39;s balance due. When <strong>Accounting</strong> is installed, posting also creates a posted journal (<strong>Dr</strong> deposit cash/bank / <strong>Cr</strong> Accounts Receivable) so the deposit account balance increases</li><li><strong>Void</strong> (<code>posted → void</code>) — reverses every allocation, rolling the linked invoices&#39; balances and statuses back, even if an invoice has since been fully paid off by another payment or deleted. When Accounting was used, the linked journal is voided as well</li></ul><p>Invalid transitions (e.g. voiding a draft payment, or posting an already-posted payment) are rejected with a validation error.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="receipt-pdf-email" tabindex="-1">Receipt PDF &amp; email <a class="header-anchor" href="#receipt-pdf-email" aria-label="Permalink to &quot;Receipt PDF &amp; email&quot;">​</a></h2><p>After you <strong>Post</strong> a payment, use <strong>Download receipt</strong> on the record page to get a branded PDF (workspace branding, payment number, paid-at, method, reference, amount, bill-to contact/company, and invoice allocation table).</p><p>Users with <strong>send</strong> (<code>payments.send</code>) can <strong>Email receipt</strong> — same dialog pattern as invoices. The <strong>To</strong> field pre-fills from the linked contact or company email when available; you can add CC recipients and edit the subject/message. Only <strong>Posted</strong> payments support PDF download and email (draft and void return an error). Delivery uses your workspace email configuration and appears in <strong>Settings → Email logs</strong>.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the payment</li><li><strong>Activity</strong> — timeline of create, update, assignment, post, void, note, emailed, and delete/restore events</li></ul><h2 id="stripe-customer-portal-online-payments-—-1-6-0" tabindex="-1">Stripe (Customer Portal online payments) — 1.6.0 <a class="header-anchor" href="#stripe-customer-portal-online-payments-—-1-6-0" aria-label="Permalink to &quot;Stripe (Customer Portal online payments) — 1.6.0&quot;">​</a></h2><p>Workspace admins/managers with <strong><code>payments.manage_integrations</code></strong> can open <strong>Payments → Stripe</strong> and connect the workspace’s own Stripe account (not EloSync SaaS billing):</p><ol><li>Paste <strong>sandbox</strong> and/or <strong>live</strong> publishable + secret keys (and webhook signing secrets).</li><li>Choose <strong>Mode</strong>: Sandbox or Live — Checkout and webhooks use only the active mode’s keys.</li><li>Enable online payments, then <strong>Test connection</strong>.</li><li>In Stripe Dashboard → Webhooks, point the endpoint URL shown in the dialog at <code>checkout.session.completed</code>, <code>checkout.session.async_payment_succeeded</code>, and <code>refund.created</code>.</li></ol><p>When Stripe is ready, Customer Portal contacts see <strong>Pay now</strong> on unpaid invoices with a balance. Successful Checkout posts a gateway <code>CustomerPayment</code> allocated to that invoice.</p><p>On a posted Stripe payment, <strong>Refund via Stripe</strong> sends the amount back to the card (partial or full, up to the refundable balance) and records the same ledger refund, invoice reversals, and accounting entry as a manual refund. Cash, bank, cheque, and other methods keep <strong>Record refund</strong> (ledger only). A refund created in the Stripe Dashboard is recorded once when <code>refund.created</code> arrives. Each Stripe refund row shows the Stripe refund id.</p><p>To credit an invoice directly (independent of a payment), see <a href="/user-guide/credit-notes">Credit Notes</a>.</p>',29)])])}const h=t(s,[["render",r]]);export{g as __pageData,h as default};
